INSERT INTO `article` VALUES (1, '意大利日新增确诊逾9万 超过50岁将强制接种疫苗', '疫苗', 521, 1, '2022-03-01 03:20:34', '2022-03-01 14:34:26', NULL, NULL, NULL, '<p>中新网2月6日电 据欧联网援引欧联通讯社报道，当地时间2月5日，意大利民政部报告新增新冠肺炎确诊病例93157例，低于前一天的99522例，而死亡病例从433例降至375例。</p><p>据报道，从2020年2月新冠病毒疫情暴发以来，意大利新冠病毒死亡病例已达148542例，是仅次于英国的欧洲第二高死亡人数。</p><p>意大利5日新冠病毒住院患者为18615人，低于前一天的19000人;重症监护室新入院人数为104人，低于4日的114人;目前重症监护患者总数已从前一天的1440人下降至1411人。</p><p>意大利卫生部5日发函更新疫情隔离规则，未接种疫苗者与患者密切接触隔离期时间将从10天缩短至5天。意大利国家新冠病毒应急委员会主任菲格利奥罗将军表示，迄今仍有大约150万50岁以上的意大利人尚未接种疫苗，对此，政府将进一步采取强制措施。</p><p>据报道，根据总理德拉吉签署的法令，从2月1日起，意大利对超过50岁以上的群体实施强制疫苗接种义务，并且对选择不接种疫苗或未及时完成接种疫苗周期的人处以100欧元罚款。</p><p>菲格利奥罗将军表示，统计资料显示，目前意大利有1516796名50岁以上的人，疫苗接种义务将于6月15日到期;50以上的新冠病毒康复者，则需在康复证明有效期六个月后，强制重新接种新冠疫苗。</p><p>菲格利奥罗将军指出，不遵守疫苗强制接种义务的50岁以上群体，如果不支付100欧元的行政罚款，将会面临资产冻结，或冻结工资及养老金的经常账户。此外，从2月15日开始，50岁以上的工作者在工作场所必须持有超级绿色通行证。无绿色通行证者，将面临600至1500欧元的罚款，并接受停薪和停职处罚。(博源)</p><p><br></p>', '/api/upload/image_1644201765016.jpg', '2022年03月23日 12:51 新浪网');
INSERT INTO `article` VALUES (2, '中国将启动新冠疫苗序贯接种，这些事必须知道', '疫苗', 140, 0, '2022-03-01 03:20:34', '2022-03-01 03:20:34', NULL, NULL, NULL, '<p class=\"ql-align-justify\">	国家卫生健康委疾控局副局长吴良有2月19日宣布，经国务院联防联控机制批准，国家卫健委已开始部署序贯加强免疫接种。</p><p class=\"ql-align-justify\">	<img src=\"https://ie--bjd--com--cn--93c36a8pd.3pco.ourwebpicvip.com/images/202202/28/621ced68e4b02e91b370b66b.png\"></p><p class=\"ql-align-justify\">	现阶段已全程接种国药中生北京公司、北京科兴公司、国药中生武汉公司的新冠病毒灭活疫苗满6个月18岁以上的目标人群，可选择康希诺生物的腺病毒载体等新冠疫苗开展1剂次序贯加强免疫接种。</p><p class=\"ql-align-justify\">	专家指出，采用腺病毒载体疫苗进行序贯加强免疫接种可大幅提高受种者的中和抗体水平，且具有较好的安全性。</p><p class=\"ql-align-justify\">	此前，我国新冠疫苗加强免疫均为“同源疫苗”接种，即前两针是灭活疫苗，第三针也接种灭活疫苗；第一针是腺病毒载体疫苗，第二针加强针也采用腺病毒载体疫苗。</p><p class=\"ql-align-justify\">	此次启动的加强针序贯接种也被称为“异源接种”（俗称 “混打”），即基础免疫和加强免疫使用不同技术路线的新冠疫苗。相当于从不同的技术路线给予身体双重“保护屏障”。</p><h4><strong>在公布“混打”之后，以下这些事必须知道：</strong></h4><h4><strong>“加强针”有了两种选择方案</strong></h4><p class=\"ql-align-justify\">	截至目前，我国有7款新冠疫苗获批附条件上市或紧急使用。包括5款灭活疫苗，1款腺病毒载体疫苗，1款重组蛋白疫苗。</p><p class=\"ql-align-justify\">	国内大多数人接种的是两针次的灭活疫苗。未来有两种选择，一种是相同技术路线加强接种，我们称为同源加强。另一种是指不同技术路线疫苗的交替接种，我们称为序贯加强。简单来说，之前打的两针灭活疫苗，加强针仍打灭活疫苗，属于同源加强；如果之前打的两针灭活疫苗，加强针打腺病毒载体新冠疫苗或重组蛋白疫苗，属于序贯加强。</p><p class=\"ql-align-justify\">	国务院联防联控机制科研攻关组疫苗研发专班工作组组长郑忠伟接受采访时表示：“通过序贯免疫的加强，抗体的水平会有更多提高”。</p><h4><strong>“异源”比“同源”更优？</strong></h4><p class=\"ql-align-justify\">	在国内大力推广加强针之际，国家卫健委疫苗研发专班专家组支持的序贯免疫研究和试点工作也取得了成果。研究表明，新冠疫苗接种后，接种者体内的抗体水平会随时间延长而有所下降。序贯接种可通过不同机制间的互补，增加免疫反应，带来更全面和强效的保护，发挥1+1&gt;2的作用。</p><p class=\"ql-align-justify\">	相比2针灭活疫苗再加1针灭活的同源免疫加强，异源加强被认为拥有更好的效果，也是对新冠疫苗加强免疫接种策略的进一步补充和完善。一段时间以来，钟南山、高福等国内知名专家均建议开展序贯加强接种。</p><h4><strong>“混打”的安全性、免疫原性怎么样？</strong></h4><p class=\"ql-align-justify\">	世界卫生组织（WHO）基于现有研究数据，发布了新冠疫苗序贯加强暂行指南。指南提出，基于现有证据，相比于仅使用灭活疫苗的同源接种程序，用载体疫苗或mRNA疫苗序贯接种时，均显示出增强的免疫原性，中和抗体水平优于灭活疫苗同源加强免疫。</p><p class=\"ql-align-justify\">	据最新公开消息，世界上已有多个国家和地区批准采用“序贯”免疫作为新冠疫苗的加强接种策略。特别是用腺病毒载体新冠疫苗，能有效为其他疫苗做加强保护，降低重症的发病率。</p><p class=\"ql-align-justify\">	比如，美国食品和药品管理局（FDA）已批准使用不同种类疫苗作为加强剂的混合接种方案。阿根廷卫生部在其官网推荐，康希诺生物的腺病毒新冠疫苗克威莎可作为加强接种疫苗，可用于已接种2剂灭活疫苗的人群。巴西卫生部表示，可采用腺病毒载体新冠疫苗作为加强免疫。智利接种两剂灭活疫苗的人群于去年8月起可接种腺病毒载体疫苗作为加强免疫。</p><p class=\"ql-align-justify\">	一些留学生此前根据当地防疫需要已经进行了“混打”，事实证明，安全有效。</p><h4><strong>未来，是否有不打针的选择？</strong></h4><p class=\"ql-align-justify\">	未来，接种新冠疫苗加强针或许还会有更好选择。康希诺生物的全球首款吸入用新冠疫苗，只需像喝奶茶一样吸上一口就完成接种过程。其不仅可激发体液及细胞免疫，还可高效诱导黏膜免疫以达到三重全面保护，具有良好的安全性及免疫原性，可为更多人建立免疫屏障。</p><h4><strong>新闻多看点：</strong></h4><h4><strong>使用康希诺生物腺病毒载体新冠疫苗序贯加强数据亮眼</strong></h4><p class=\"ql-align-justify\">	使用腺病毒载体疫苗进行序贯加强免疫的优势已在多项临床研究中得到证实。此前，江苏省疾病预防控制中心团队开展的序贯加强免疫临床试验结果表明，使用灭活疫苗进行基础免疫、用康希诺生物腺病毒载体新冠疫苗克威莎做序贯加强，中和抗体水平为灭活疫苗同源加强的5倍。接种2剂灭活疫苗后，再接种1剂克威莎作为加强，14天后中和抗体水平为197.4 (95%CI 167.7, 232.4)，若第3剂用灭活疫苗进行加强，抗体水平为33.6 (95%CI 28.3, 39.8)。</p><p class=\"ql-align-justify\">	由中国科学院病原微生物与免疫学重点实验室、中国科学院微生物学研究所等多个合作单位共同发表了最新序贯加强研究结果。数据表明，已完成2剂灭活疫苗接种4-8个月的受试者中，以不同技术路线新冠疫苗做同源或序贯加强，康希诺生物腺病毒载体新冠疫苗克威莎的免疫效果最强，针对原始毒株的中和抗体水平是重组蛋白疫苗序贯加强的7倍。此外，该研究结果显示，采用克威莎加强免疫能对奥密克戎突变株提供最强的保护，中和抗体水平是灭活疫苗同源加强的6倍，重组蛋白疫苗序贯加强的3倍。</p><p><br></p>', '/api/upload/image_1646098884777.jpg', '中国将启动新冠疫苗序贯接种，这些事必须知道');
INSERT INTO `article` VALUES (3, '中国将启动新冠疫苗序贯接种，这些事必须知道', '疫苗', 162, 0, '2022-03-01 03:20:34', '2022-03-01 03:20:34', NULL, NULL, NULL, '<p class=\"ql-align-justify\">	国家卫生健康委疾控局副局长吴良有2月19日宣布，经国务院联防联控机制批准，国家卫健委已开始部署序贯加强免疫接种。</p><p class=\"ql-align-justify\">	<img src=\"https://ie--bjd--com--cn--93c36a8pd.3pco.ourwebpicvip.com/images/202202/28/621ced68e4b02e91b370b66b.png\"></p><p class=\"ql-align-justify\">	现阶段已全程接种国药中生北京公司、北京科兴公司、国药中生武汉公司的新冠病毒灭活疫苗满6个月18岁以上的目标人群，可选择康希诺生物的腺病毒载体等新冠疫苗开展1剂次序贯加强免疫接种。</p><p class=\"ql-align-justify\">	专家指出，采用腺病毒载体疫苗进行序贯加强免疫接种可大幅提高受种者的中和抗体水平，且具有较好的安全性。</p><p class=\"ql-align-justify\">	此前，我国新冠疫苗加强免疫均为“同源疫苗”接种，即前两针是灭活疫苗，第三针也接种灭活疫苗；第一针是腺病毒载体疫苗，第二针加强针也采用腺病毒载体疫苗。</p><p class=\"ql-align-justify\">	此次启动的加强针序贯接种也被称为“异源接种”（俗称 “混打”），即基础免疫和加强免疫使用不同技术路线的新冠疫苗。相当于从不同的技术路线给予身体双重“保护屏障”。</p><h4><strong>在公布“混打”之后，以下这些事必须知道：</strong></h4><h4><strong>“加强针”有了两种选择方案</strong></h4><p class=\"ql-align-justify\">	截至目前，我国有7款新冠疫苗获批附条件上市或紧急使用。包括5款灭活疫苗，1款腺病毒载体疫苗，1款重组蛋白疫苗。</p><p class=\"ql-align-justify\">	国内大多数人接种的是两针次的灭活疫苗。未来有两种选择，一种是相同技术路线加强接种，我们称为同源加强。另一种是指不同技术路线疫苗的交替接种，我们称为序贯加强。简单来说，之前打的两针灭活疫苗，加强针仍打灭活疫苗，属于同源加强；如果之前打的两针灭活疫苗，加强针打腺病毒载体新冠疫苗或重组蛋白疫苗，属于序贯加强。</p><p class=\"ql-align-justify\">	国务院联防联控机制科研攻关组疫苗研发专班工作组组长郑忠伟接受采访时表示：“通过序贯免疫的加强，抗体的水平会有更多提高”。</p><h4><strong>“异源”比“同源”更优？</strong></h4><p class=\"ql-align-justify\">	在国内大力推广加强针之际，国家卫健委疫苗研发专班专家组支持的序贯免疫研究和试点工作也取得了成果。研究表明，新冠疫苗接种后，接种者体内的抗体水平会随时间延长而有所下降。序贯接种可通过不同机制间的互补，增加免疫反应，带来更全面和强效的保护，发挥1+1&gt;2的作用。</p><p class=\"ql-align-justify\">	相比2针灭活疫苗再加1针灭活的同源免疫加强，异源加强被认为拥有更好的效果，也是对新冠疫苗加强免疫接种策略的进一步补充和完善。一段时间以来，钟南山、高福等国内知名专家均建议开展序贯加强接种。</p><h4><strong>“混打”的安全性、免疫原性怎么样？</strong></h4><p class=\"ql-align-justify\">	世界卫生组织（WHO）基于现有研究数据，发布了新冠疫苗序贯加强暂行指南。指南提出，基于现有证据，相比于仅使用灭活疫苗的同源接种程序，用载体疫苗或mRNA疫苗序贯接种时，均显示出增强的免疫原性，中和抗体水平优于灭活疫苗同源加强免疫。</p><p class=\"ql-align-justify\">	据最新公开消息，世界上已有多个国家和地区批准采用“序贯”免疫作为新冠疫苗的加强接种策略。特别是用腺病毒载体新冠疫苗，能有效为其他疫苗做加强保护，降低重症的发病率。</p><p class=\"ql-align-justify\">	比如，美国食品和药品管理局（FDA）已批准使用不同种类疫苗作为加强剂的混合接种方案。阿根廷卫生部在其官网推荐，康希诺生物的腺病毒新冠疫苗克威莎可作为加强接种疫苗，可用于已接种2剂灭活疫苗的人群。巴西卫生部表示，可采用腺病毒载体新冠疫苗作为加强免疫。智利接种两剂灭活疫苗的人群于去年8月起可接种腺病毒载体疫苗作为加强免疫。</p><p class=\"ql-align-justify\">	一些留学生此前根据当地防疫需要已经进行了“混打”，事实证明，安全有效。</p><h4><strong>未来，是否有不打针的选择？</strong></h4><p class=\"ql-align-justify\">	未来，接种新冠疫苗加强针或许还会有更好选择。康希诺生物的全球首款吸入用新冠疫苗，只需像喝奶茶一样吸上一口就完成接种过程。其不仅可激发体液及细胞免疫，还可高效诱导黏膜免疫以达到三重全面保护，具有良好的安全性及免疫原性，可为更多人建立免疫屏障。</p><h4><strong>新闻多看点：</strong></h4><h4><strong>使用康希诺生物腺病毒载体新冠疫苗序贯加强数据亮眼</strong></h4><p class=\"ql-align-justify\">	使用腺病毒载体疫苗进行序贯加强免疫的优势已在多项临床研究中得到证实。此前，江苏省疾病预防控制中心团队开展的序贯加强免疫临床试验结果表明，使用灭活疫苗进行基础免疫、用康希诺生物腺病毒载体新冠疫苗克威莎做序贯加强，中和抗体水平为灭活疫苗同源加强的5倍。接种2剂灭活疫苗后，再接种1剂克威莎作为加强，14天后中和抗体水平为197.4 (95%CI 167.7, 232.4)，若第3剂用灭活疫苗进行加强，抗体水平为33.6 (95%CI 28.3, 39.8)。</p><p class=\"ql-align-justify\">	由中国科学院病原微生物与免疫学重点实验室、中国科学院微生物学研究所等多个合作单位共同发表了最新序贯加强研究结果。数据表明，已完成2剂灭活疫苗接种4-8个月的受试者中，以不同技术路线新冠疫苗做同源或序贯加强，康希诺生物腺病毒载体新冠疫苗克威莎的免疫效果最强，针对原始毒株的中和抗体水平是重组蛋白疫苗序贯加强的7倍。此外，该研究结果显示，采用克威莎加强免疫能对奥密克戎突变株提供最强的保护，中和抗体水平是灭活疫苗同源加强的6倍，重组蛋白疫苗序贯加强的3倍。</p><p><br></p>', '/api/upload/image_1646098884777.jpg', '中国将启动新冠疫苗序贯接种，这些事必须知道');
INSERT INTO `article` VALUES (4, '新闻中心> 加强疫苗合作 共筑免疫屏障', '疫苗', 41, 0, '2022-03-01 03:20:34', '2022-03-01 03:20:34', NULL, NULL, NULL, '<p>	中国是团结抗疫的积极倡导者、务实行动派，是疫苗公平分配的最大贡献者，是疫苗合作生产的坚定践行者，是疫苗多边合作的积极参与者</p><p>	2月25日，联合国大会新冠疫苗高级别会议举行。在新冠肺炎疫情已延宕两年、疫苗分配不公现象仍在严重影响着全球抗疫进程的重要关头，各国代表共同探讨普及疫苗接种之策，呼吁全球团结起来、激发动力，加速全球范围内的新冠疫苗接种。正如联大主席沙希德在会议上指出的，“我们的力量在于团结”。人类必须团结在一起，尽早实现全球疫苗接种目标，才能尽早结束疫情大流行。</p><p>	习近平主席不久前在会见联合国秘书长古特雷斯时指出，当前和今后一个时期，世界上有三件大事值得认真思考和关注。团结抗疫是习近平主席提到的第一件大事。当前，全球已接种超过100亿剂疫苗，但非洲仍有约83%的人口尚未接种一剂疫苗，27个国家的接种率不到10%，实现疫苗公平可及分配、消除“免疫鸿沟”是当务之急。作为全球公共产品的提供者，中国秉持人类卫生健康共同体理念，为全球团结抗疫作出重要贡献，赢得国际社会广泛赞誉。</p><p>	中国是团结抗疫的积极倡导者和务实行动派。中国坚定支持全球团结抗疫，最早提出并积极践行将疫苗作为全球公共产品的承诺。习近平主席去年提出全球疫苗合作行动倡议，核心就是加快实现疫苗在发展中国家的公平可及，早日构筑起“免疫屏障”。习近平主席在2022年世界经济论坛视频会议上强调：“特别是要用好疫苗这个有力武器，确保疫苗公平分配，加快推进接种速度，弥合国际‘免疫鸿沟’，把生命健康守护好、把人民生活保障好。”古特雷斯感谢中国政府为发展中国家疫苗可及性作出了贡献。</p><p>	中国是疫苗公平分配的最大贡献者。中国言必信，行必果，全力支持联合国提出的今年年中70%人口接种疫苗的目标，迄今已向120多个国家和国际组织提供超过21亿剂疫苗，成为对外提供疫苗最多的国家。全球使用的疫苗中，每两支就有一支是“中国制造”。很多国家特别是发展中国家迄今获得的大多数疫苗来自中国。中国提供的疫苗增强了发展中国家抗疫的能力、信心和决心。全球疫苗免疫联盟首席执行官伯克利强调：“这是中国为全球抗疫作出的重要贡献。”</p><p>	中国是疫苗合作生产的坚定践行者。中国最早支持疫苗知识产权豁免，率先向发展中国家转让技术，迄今已同20国开展合作生产，形成10亿剂年产能。2月20日，中国和埃及联合向加沙地带援助50万剂新冠疫苗，这是埃及首次对外提供中埃联合生产的疫苗。埃及代理卫生部长加法尔表示，埃中两国公司合作建立的非洲大陆首条新冠疫苗生产线已生产约3000万剂安全、有效的疫苗。中国以实际行动增强发展中国家的疫苗生产能力，树立起团结抗疫的标杆。</p><p>	中国是疫苗多边合作的积极参与者。中国支持世界卫生组织发挥中心协调作用，优先保障“新冠疫苗实施计划”采购需求，已经向该计划供应超过2亿剂疫苗。中国还向该计划捐赠1亿美元，用于向发展中国家分配新冠疫苗。在联合国大会新冠疫苗高级别会议上，中方提出织牢免疫“安全网”、丰富抗疫“武器库”、完善卫生“治理盾”、 强化发展“稳定锚”四点建议，展现出支持多边合作的坚定意志。</p><p>	“孤举者难起，众行者易趋。”世界只要存在免疫“缺口”，就不可能彻底安全。国际社会必须将疫苗作为全球公共产品，担起应尽职责，发挥多边机制作用，切实促进疫苗的公平性、可及性、可负担性。中国愿继续同各方一道，携手加强疫苗合作，同心共筑免疫长城，不断汇聚团结抗疫的强大力量。</p>', '/api/upload/image_1646098781096.jpg', '加强疫苗合作 共筑免疫屏障');
INSERT INTO `article` VALUES (5, '中国将启动新冠疫苗序贯接种，这些事必须知道', '疫苗', 862, 0, '2022-03-01 03:20:34', '2022-03-01 03:20:34', NULL, NULL, NULL, '<p class=\"ql-align-justify\">	国家卫生健康委疾控局副局长吴良有2月19日宣布，经国务院联防联控机制批准，国家卫健委已开始部署序贯加强免疫接种。</p><p class=\"ql-align-justify\">	<img src=\"https://ie--bjd--com--cn--93c36a8pd.3pco.ourwebpicvip.com/images/202202/28/621ced68e4b02e91b370b66b.png\"></p><p class=\"ql-align-justify\">	现阶段已全程接种国药中生北京公司、北京科兴公司、国药中生武汉公司的新冠病毒灭活疫苗满6个月18岁以上的目标人群，可选择康希诺生物的腺病毒载体等新冠疫苗开展1剂次序贯加强免疫接种。</p><p class=\"ql-align-justify\">	专家指出，采用腺病毒载体疫苗进行序贯加强免疫接种可大幅提高受种者的中和抗体水平，且具有较好的安全性。</p><p class=\"ql-align-justify\">	此前，我国新冠疫苗加强免疫均为“同源疫苗”接种，即前两针是灭活疫苗，第三针也接种灭活疫苗；第一针是腺病毒载体疫苗，第二针加强针也采用腺病毒载体疫苗。</p><p class=\"ql-align-justify\">	此次启动的加强针序贯接种也被称为“异源接种”（俗称 “混打”），即基础免疫和加强免疫使用不同技术路线的新冠疫苗。相当于从不同的技术路线给予身体双重“保护屏障”。</p><h4><strong>在公布“混打”之后，以下这些事必须知道：</strong></h4><h4><strong>“加强针”有了两种选择方案</strong></h4><p class=\"ql-align-justify\">	截至目前，我国有7款新冠疫苗获批附条件上市或紧急使用。包括5款灭活疫苗，1款腺病毒载体疫苗，1款重组蛋白疫苗。</p><p class=\"ql-align-justify\">	国内大多数人接种的是两针次的灭活疫苗。未来有两种选择，一种是相同技术路线加强接种，我们称为同源加强。另一种是指不同技术路线疫苗的交替接种，我们称为序贯加强。简单来说，之前打的两针灭活疫苗，加强针仍打灭活疫苗，属于同源加强；如果之前打的两针灭活疫苗，加强针打腺病毒载体新冠疫苗或重组蛋白疫苗，属于序贯加强。</p><p class=\"ql-align-justify\">	国务院联防联控机制科研攻关组疫苗研发专班工作组组长郑忠伟接受采访时表示：“通过序贯免疫的加强，抗体的水平会有更多提高”。</p><h4><strong>“异源”比“同源”更优？</strong></h4><p class=\"ql-align-justify\">	在国内大力推广加强针之际，国家卫健委疫苗研发专班专家组支持的序贯免疫研究和试点工作也取得了成果。研究表明，新冠疫苗接种后，接种者体内的抗体水平会随时间延长而有所下降。序贯接种可通过不同机制间的互补，增加免疫反应，带来更全面和强效的保护，发挥1+1&gt;2的作用。</p><p class=\"ql-align-justify\">	相比2针灭活疫苗再加1针灭活的同源免疫加强，异源加强被认为拥有更好的效果，也是对新冠疫苗加强免疫接种策略的进一步补充和完善。一段时间以来，钟南山、高福等国内知名专家均建议开展序贯加强接种。</p><h4><strong>“混打”的安全性、免疫原性怎么样？</strong></h4><p class=\"ql-align-justify\">	世界卫生组织（WHO）基于现有研究数据，发布了新冠疫苗序贯加强暂行指南。指南提出，基于现有证据，相比于仅使用灭活疫苗的同源接种程序，用载体疫苗或mRNA疫苗序贯接种时，均显示出增强的免疫原性，中和抗体水平优于灭活疫苗同源加强免疫。</p><p class=\"ql-align-justify\">	据最新公开消息，世界上已有多个国家和地区批准采用“序贯”免疫作为新冠疫苗的加强接种策略。特别是用腺病毒载体新冠疫苗，能有效为其他疫苗做加强保护，降低重症的发病率。</p><p class=\"ql-align-justify\">	比如，美国食品和药品管理局（FDA）已批准使用不同种类疫苗作为加强剂的混合接种方案。阿根廷卫生部在其官网推荐，康希诺生物的腺病毒新冠疫苗克威莎可作为加强接种疫苗，可用于已接种2剂灭活疫苗的人群。巴西卫生部表示，可采用腺病毒载体新冠疫苗作为加强免疫。智利接种两剂灭活疫苗的人群于去年8月起可接种腺病毒载体疫苗作为加强免疫。</p><p class=\"ql-align-justify\">	一些留学生此前根据当地防疫需要已经进行了“混打”，事实证明，安全有效。</p><h4><strong>未来，是否有不打针的选择？</strong></h4><p class=\"ql-align-justify\">	未来，接种新冠疫苗加强针或许还会有更好选择。康希诺生物的全球首款吸入用新冠疫苗，只需像喝奶茶一样吸上一口就完成接种过程。其不仅可激发体液及细胞免疫，还可高效诱导黏膜免疫以达到三重全面保护，具有良好的安全性及免疫原性，可为更多人建立免疫屏障。</p><h4><strong>新闻多看点：</strong></h4><h4><strong>使用康希诺生物腺病毒载体新冠疫苗序贯加强数据亮眼</strong></h4><p class=\"ql-align-justify\">	使用腺病毒载体疫苗进行序贯加强免疫的优势已在多项临床研究中得到证实。此前，江苏省疾病预防控制中心团队开展的序贯加强免疫临床试验结果表明，使用灭活疫苗进行基础免疫、用康希诺生物腺病毒载体新冠疫苗克威莎做序贯加强，中和抗体水平为灭活疫苗同源加强的5倍。接种2剂灭活疫苗后，再接种1剂克威莎作为加强，14天后中和抗体水平为197.4 (95%CI 167.7, 232.4)，若第3剂用灭活疫苗进行加强，抗体水平为33.6 (95%CI 28.3, 39.8)。</p><p class=\"ql-align-justify\">	由中国科学院病原微生物与免疫学重点实验室、中国科学院微生物学研究所等多个合作单位共同发表了最新序贯加强研究结果。数据表明，已完成2剂灭活疫苗接种4-8个月的受试者中，以不同技术路线新冠疫苗做同源或序贯加强，康希诺生物腺病毒载体新冠疫苗克威莎的免疫效果最强，针对原始毒株的中和抗体水平是重组蛋白疫苗序贯加强的7倍。此外，该研究结果显示，采用克威莎加强免疫能对奥密克戎突变株提供最强的保护，中和抗体水平是灭活疫苗同源加强的6倍，重组蛋白疫苗序贯加强的3倍。</p><p><br></p>', '/api/upload/image_1646098884777.jpg', '中国将启动新冠疫苗序贯接种，这些事必须知道');
INSERT INTO `article` VALUES (6, '意大利日新增确诊逾9万 超过50岁将强制接种疫苗', '疫苗', 903, 0, '2022-03-01 03:20:34', '2022-03-01 03:20:34', NULL, NULL, NULL, '<p>中新网2月6日电 据欧联网援引欧联通讯社报道，当地时间2月5日，意大利民政部报告新增新冠肺炎确诊病例93157例，低于前一天的99522例，而死亡病例从433例降至375例。</p><p>据报道，从2020年2月新冠病毒疫情暴发以来，意大利新冠病毒死亡病例已达148542例，是仅次于英国的欧洲第二高死亡人数。</p><p>意大利5日新冠病毒住院患者为18615人，低于前一天的19000人;重症监护室新入院人数为104人，低于4日的114人;目前重症监护患者总数已从前一天的1440人下降至1411人。</p><p>意大利卫生部5日发函更新疫情隔离规则，未接种疫苗者与患者密切接触隔离期时间将从10天缩短至5天。意大利国家新冠病毒应急委员会主任菲格利奥罗将军表示，迄今仍有大约150万50岁以上的意大利人尚未接种疫苗，对此，政府将进一步采取强制措施。</p><p>据报道，根据总理德拉吉签署的法令，从2月1日起，意大利对超过50岁以上的群体实施强制疫苗接种义务，并且对选择不接种疫苗或未及时完成接种疫苗周期的人处以100欧元罚款。</p><p>菲格利奥罗将军表示，统计资料显示，目前意大利有1516796名50岁以上的人，疫苗接种义务将于6月15日到期;50以上的新冠病毒康复者，则需在康复证明有效期六个月后，强制重新接种新冠疫苗。</p><p>菲格利奥罗将军指出，不遵守疫苗强制接种义务的50岁以上群体，如果不支付100欧元的行政罚款，将会面临资产冻结，或冻结工资及养老金的经常账户。此外，从2月15日开始，50岁以上的工作者在工作场所必须持有超级绿色通行证。无绿色通行证者，将面临600至1500欧元的罚款，并接受停薪和停职处罚。(博源)</p><p><br></p>', '/api/upload/image_1644201765016.jpg', '2022年03月23日 12:51 新浪网');
INSERT INTO `article` VALUES (7, '疫苗的好处', '疫苗', 0, 0, '2022-03-01 14:38:30', '2022-03-01 14:38:30', '', '', '疫苗的好处', '<p>按时交付和卡就十大富豪空间的复活卡健身房就卡死的回复看就卡号发的就客户答复</p><p>世界的繁华科技孵化快捷回复快捷回复卡撒娇的发货<img src=\"data:image/jpeg;base64,\"></p>', '/api/upload/u=287232593,345133632&fm=26&fmt=auto.jpg', '疫苗的好处');

-- ----------------------------
-- Table structure for article_type
-- ----------------------------
DROP TABLE IF EXISTS `article_type`;
CREATE TABLE `article_type`  (
  `type_id` smallint(5) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '分类ID：[0,10000]',
  `display` smallint(4) UNSIGNED NOT NULL DEFAULT 100 COMMENT '显示顺序：[0,1000]决定分类显示的先后顺序',
  `name` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分类名称：[2,16]',
  `father_id` smallint(5) UNSIGNED NOT NULL DEFAULT 0 COMMENT '上级分类ID：[0,32767]',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '描述：[0,255]描述该分类的作用',
  `icon` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '分类图标：',
  `url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '外链地址：[0,255]如果该分类是跳转到其他网站的情况下，就在该URL上设置',
  `create_time` timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP(0) COMMENT '创建时间：',
  `update_time` timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间：',
  PRIMARY KEY (`type_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '文章频道：用于汇总浏览文章，在不同频道下展示不同文章。' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of article_type
-- ----------------------------
INSERT INTO `article_type` VALUES (1, 100, '疫苗', 0, NULL, NULL, NULL, '2022-03-01 03:20:34', '2022-03-01 03:20:34');
