DROP TABLE IF EXISTS `vaccine_information`;
CREATE TABLE `vaccine_information`  (
  `vaccine_information_id` int(11) NOT NULL AUTO_INCREMENT COMMENT '疫苗信息ID',
  `vaccine_number` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '疫苗编号',
  `vaccine_type` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '疫苗类型',
  `vaccine_name` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '疫苗名称',
  `suitable_for_people` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '适合人群',
  `vaccine_producing_area` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '疫苗出产地',
  `picture` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '图片',
  `stock` int(11) NULL DEFAULT 0 COMMENT '库存',
  `vaccine_introduction` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '疫苗简介',
  `side_effect` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '副作用',
  `hits` int(11) NOT NULL DEFAULT 0 COMMENT '点击数',
  `recommend` int(11) NOT NULL DEFAULT 0 COMMENT '智能推荐',
